     1	import { config } from '../config';
     2	import { sign } from '../auth';
     3	export class BankError extends Error {
     4	  constructor(
     5	    public status: number,
     6	    message: string,
     7	  ) {
     8	    super(message);
     9	  }
    10	}
    11	export async function bankRequest<T>(
    12	  userId: string,
    13	  path: string,
    14	  method = 'GET',
    15	  body?: unknown,
    16	): Promise<T> {
    17	  const raw = body === undefined ? '' : JSON.stringify(body),
    18	    timestamp = String(Date.now());
    19	  const signature = sign([method, path, userId, timestamp, raw].join('\n'), config.serviceSecret);
    20	  let response: Response;
    21	  try {
    22	    response = await fetch(`${config.bankUrl}${path}`, {
    23	      method,
    24	      headers: {
    25	        'Content-Type': 'application/json',
    26	        'x-bank-actor': userId,
    27	        'x-bank-time': timestamp,
    28	        'x-bank-signature': signature,
    29	      },
    30	      body: raw || undefined,
    31	      signal: AbortSignal.timeout(config.bankTimeoutMs),
    32	      cache: 'no-store',
    33	    });
    34	  } catch {
    35	    throw new BankError(504, 'No response received from the bank.');
    36	  }
    37	  let data: any;
    38	  try {
    39	    data = await response.json();
    40	  } catch {
    41	    throw new BankError(502, 'Unreadable bank response.');
    42	  }
    43	  if (!response.ok) throw new BankError(response.status, data.error || 'Bank service error.');
    44	  return data as T;
    45	}
