    10	import type { ToolContext } from '../types';
    11	const object = (properties: Record<string, unknown>) => ({
    12	  type: 'object',
    13	  properties,
    14	  required: Object.keys(properties),
    15	  additionalProperties: false,
    16	});
    17	const string = { type: 'string' };
    18	export const toolDefinitions: FunctionTool[] = [
    19	  {
    20	    type: 'function',
    21	    name: 'list_accounts',
    22	    description: "Get the current customer's accounts, balances, and available recipients.",
    23	    parameters: object({}),
    24	    strict: true,
    25	  },
    26	  {
    27	    type: 'function',
    28	    name: 'search_documents',
    29	    description: "Search the bank's documentation for policies and procedures.",
    30	    parameters: object({
    31	      query: string,
    32	      includeArchived: {
    33	        type: 'boolean',
    34	        description: 'Set true only when the customer asks about past or historical terms.',
    35	      },
    36	    }),
    37	    strict: true,
    38	  },
    39	  {
    40	    type: 'function',
    41	    name: 'transfer_money',
    42	    description:
    43	      'Propose a transfer between simulator accounts. Returns a proposal that the customer must confirm before any money moves. Amounts are integer cents.',
    44	    parameters: object({
    45	      fromAccountId: string,
    46	      toAccountId: string,
    47	      amountCents: { type: 'integer' },
    48	      concept: string,
    49	    }),
    50	    strict: true,
    51	  },
    52	  {
    53	    type: 'function',
    54	    name: 'confirm_transfer',
    55	    description:
    56	      'Execute a transfer proposal after the customer has explicitly confirmed its exact summary in a later message.',
    57	    parameters: object({ approvalId: string }),
    58	    strict: true,
    59	  },
    60	  {
    61	    type: 'function',
    62	    name: 'operation_status',
    63	    description: 'Look up an operation by its bank reference.',
    64	    parameters: object({ reference: string }),
    65	    strict: true,
    66	  },
    67	  {
    68	    type: 'function',
    69	    name: 'request_human',
    70	    description: 'Open a human support case for this conversation.',
    71	    parameters: object({ summary: string }),
    72	    strict: true,
    73	  },
    74	];
    75	export async function runTool(name: string, args: unknown, ctx: ToolContext): Promise<unknown> {
    76	  const started = Date.now();
    77	  recordEvent(ctx, 'tool.started', { tool: name, status: 'started', arguments: args });
    78	  let result: unknown;
    79	  try {
    80	    switch (name) {
    81	      case 'list_accounts':
    82	        result = {
    83	          accounts: await bankRequest(ctx.userId, '/v1/accounts'),
    84	          contacts: await bankRequest(ctx.userId, '/v1/contacts'),
    85	        };
    86	        break;
    87	      case 'search_documents': {
    88	        const { query, includeArchived } = z
    89	          .object({ query: z.string().max(2000), includeArchived: z.boolean() })
    90	          .parse(args);
    91	        result = { sources: await searchDocuments(query, 'customer', 5, includeArchived) };
    92	        break;
    93	      }
    94	      case 'transfer_money':
    95	        result = await transferMoney(ctx, args);
    96	        break;
    97	      case 'confirm_transfer': {
    98	        const { approvalId } = z.object({ approvalId: z.string() }).parse(args);
    99	        const approval = appDb()
   100	          .prepare('SELECT * FROM approvals WHERE id=? AND user_id=?')
   101	          .get(approvalId, ctx.userId) as { intent_id: string; payload: string } | undefined;
   102	        result = approval
   103	          ? await transferMoney(
   104	              { ...ctx, intentId: approval.intent_id, approvalId, confirmedBy: 'message' },
   105	              JSON.parse(approval.payload),
   106	            )
   107	          : { status: 'failed', error: 'Proposal not found.' };
   108	        break;
   109	      }
   110	      case 'operation_status': {
   111	        const reference = z.object({ reference: z.string() }).parse(args).reference;
   112	        result = await bankRequest(ctx.userId, `/v1/operations/${encodeURIComponent(reference)}`);
   113	        const pending = appDb()
   114	          .prepare(
   115	            "SELECT id FROM intents WHERE user_id=? AND bank_reference=? AND status='unknown'",
   116	          )
   117	          .get(ctx.userId, reference) as { id: string } | undefined;
   118	        if (pending) result = await resolveIntent(ctx.userId, pending.id);
   119	        break;
   120	      }
   121	      case 'request_human': {
   122	        if (!ctx.conversationId) throw new Error('A conversation is required to open a case.');
   123	        const { summary } = z.object({ summary: z.string().min(1).max(2000) }).parse(args);
   124	        const existing = appDb()
   125	          .prepare('SELECT id FROM incidents WHERE conversation_id=? AND status=?')
   126	          .get(ctx.conversationId, 'open') as { id: string } | undefined;
   127	        const id = existing?.id || randomUUID();
   128	        if (!existing)
   129	          appDb()
   130	            .prepare('INSERT INTO incidents VALUES(?,?,?,?,?,?)')
   131	            .run(id, ctx.userId, ctx.conversationId, summary, 'open', new Date().toISOString());
   132	        result = { status: 'open', incidentId: id };
   133	        break;
   134	      }
   135	      default:
   136	        throw new Error('Unknown tool.');
   137	    }
   138	    recordEvent(ctx, 'tool.completed', {
   139	      tool: name,
   140	      status: 'completed',
   141	      arguments: args,
   142	      output: result,
   143	      durationMs: Date.now() - started,
   144	    });
   145	    return result;
   146	  } catch (e) {
   147	    const error = e instanceof Error ? e.message : 'Tool error';
   148	    recordEvent(ctx, 'tool.failed', {
   149	      tool: name,
   150	      status: 'failed',
   151	      arguments: args,
   152	      error,
   153	      durationMs: Date.now() - started,
   154	    });
   155	    return { status: 'failed', error };
   156	  }
   157	}

