    11	export async function authorizeTransfer(
    12	  ctx: ToolContext,
    13	  input: TransferInput,
    14	): Promise<ActionResult | null> {
    15	  const db = appDb();
    16	  if (!ctx.approvalId) {
    17	    const unverified = db
    18	      .prepare(
    19	        "SELECT id,bank_reference FROM intents WHERE user_id=? AND payload=? AND status IN ('unknown','processing') AND id!=?",
    20	      )
    21	      .all(ctx.userId, JSON.stringify(input), ctx.intentId) as {
    22	      id: string;
    23	      bank_reference: string | null;
    24	    }[];
    25	    for (const pending of unverified) {
    26	      const resolved = await resolveIntent(ctx.userId, pending.id);
    27	      if (resolved.status === 'unknown') {
    28	        db.prepare("UPDATE intents SET status='blocked' WHERE id=?").run(ctx.intentId);
    29	        return {
    30	          status: 'blocked',
    31	          code: 'pending_verification',
    32	          intentId: pending.id,
    33	          reference: pending.bank_reference,
    34	          error: `An identical transfer is still awaiting the bank's confirmation (reference ${pending.bank_reference}). It will be verified before any new transfer with the same details.`,
    35	        };
    36	      }
    37	    }
    38	    const accounts = await bankRequest<Account[]>(ctx.userId, '/v1/accounts');
    39	    const from = accounts.find((a) => a.id === input.fromAccountId);
    40	    if (!from) throw new HttpError(403, 'This account does not belong to this person.');
    41	    const contacts = await bankRequest<(Account & { name?: string })[]>(ctx.userId, '/v1/contacts');
    42	    const to = contacts.find((c) => c.id === input.toAccountId);
    43	    const proposal = {
    44	      fromAccountId: from.id,
    45	      fromLabel: from.label,
    46	      toAccountId: input.toAccountId,
    47	      toName: to?.name || null,
    48	      toLabel: to?.label || null,
    49	      amountCents: input.amountCents,
    50	      concept: input.concept,
    51	    };
    52	    const approvalId = randomUUID(),
    53	      expiresAt = new Date(Date.now() + 10 * 60 * 1000).toISOString();
    54	    db.prepare('INSERT INTO approvals VALUES(?,?,?,?,?,?)').run(
    55	      approvalId,
    56	      ctx.userId,
    57	      ctx.intentId,
    58	      JSON.stringify(input),
    59	      expiresAt,
    60	      null,
    61	    );
    62	    db.prepare("UPDATE intents SET status='awaiting_confirmation' WHERE id=?").run(ctx.intentId);
    63	    recordEvent(ctx, 'transfer.proposed', {
    64	      status: 'awaiting_confirmation',
    65	      approvalId,
    66	      input,
    67	      intentId: ctx.intentId,
    68	    });
    69	    return {
    70	      status: 'requires_confirmation',
    71	      approvalId,
    72	      intentId: ctx.intentId,
    73	      expiresAt,
    74	      confirmationCode: confirmationCode(approvalId),
    75	      proposal,
    76	    };
    77	  }
    78	  const accounts = await bankRequest<Account[]>(ctx.userId, '/v1/accounts');
    79	  if (!accounts.some((a) => a.id === input.fromAccountId))
    80	    throw new HttpError(403, 'This account does not belong to this person.');
    81	  const approval = db.prepare('SELECT * FROM approvals WHERE id=?').get(ctx.approvalId) as
    82	    | {
    83	        user_id: string;
    84	        intent_id: string;
    85	        payload: string;
    86	        expires_at: string;
    87	        consumed_at: string | null;
    88	      }
    89	    | undefined;
    90	  if (!approval || approval.user_id !== ctx.userId || approval.intent_id !== ctx.intentId)
    91	    return fail('not_found', 'Proposal not found.');
    92	  if (approval.payload !== JSON.stringify(input))
    93	    return fail('mismatch', 'The proposal does not match these details.');
    94	  const intent = db.prepare('SELECT status FROM intents WHERE id=?').get(ctx.intentId) as
    95	    { status: string } | undefined;
    96	  if (
    97	    intent?.status === 'awaiting_confirmation' &&
    98	    approval.expires_at <= new Date().toISOString()
    99	  ) {
   100	    db.prepare("UPDATE intents SET status='expired' WHERE id=?").run(ctx.intentId);
   101	    return fail('expired', 'This proposal has expired. Ask for a new one.');
   102	  }
   103	  if (approval.consumed_at && intent?.status !== 'unknown')
   104	    return fail('already_used', 'This proposal was already used.');
   105	  if (!ctx.confirmedBy) return fail('channel_unknown', 'Confirmation channel unknown.');
   106	  if (ctx.confirmedBy === 'message') {
   107	    const message = db
   108	      .prepare("SELECT content FROM messages WHERE run_id=? AND role='user'")
   109	      .get(ctx.runId) as { content: string } | undefined;
   110	    const normalized = (message?.content || '').toUpperCase().replace(/[\s-]/g, '');
   111	    if (!normalized.includes(confirmationCode(ctx.approvalId)))
