   113	        'code_required',
   114	        'Ask the customer to reply with the confirmation code shown in the proposal.',
   115	      );
   116	  }
   117	  const consumed = db
   118	    .prepare('UPDATE approvals SET consumed_at=? WHERE id=? AND consumed_at IS NULL')
   119	    .run(new Date().toISOString(), ctx.approvalId);
   120	  if (consumed.changes === 0 && intent?.status !== 'unknown')
   121	    return fail('already_used', 'This proposal was already used.');
   122	  return null;
   123	}
