     7	export async function resolveIntent(userId: string, intentId: string): Promise<ActionResult> {
     8	  const db = appDb();
     9	  const intent = db
    10	    .prepare('SELECT * FROM intents WHERE id=? AND user_id=?')
    11	    .get(intentId, userId) as
    12	    | {
    13	        status: string;
    14	        bank_reference: string | null;
    15	        operation_id: string | null;
    16	        error: string | null;
    17	        conversation_id: string | null;
    18	      }
    19	    | undefined;
    20	  if (!intent || intent.status !== 'unknown' || !intent.bank_reference)
    21	    return { status: intent?.status || 'unknown', intentId };
    22	  const ctx: ToolContext = {
    23	    userId,
    24	    conversationId: intent.conversation_id,
    25	    runId: randomUUID(),
    26	    intentId,
    27	  };
    28	  try {
    29	    const operation = await bankRequest<Operation>(
    30	      userId,
    31	      `/v1/operations/${encodeURIComponent(intent.bank_reference)}`,
    32	    );
    33	    db.prepare("UPDATE intents SET status='completed',operation_id=?,error=NULL WHERE id=?").run(
    34	      operation.id,
    35	      intentId,
    36	    );
    37	    recordEvent(ctx, 'transfer.resolved', { status: 'completed', operation, intentId });
    38	    return { status: 'completed', operation, intentId, resolved: true };
    39	  } catch (e) {
    40	    if (e instanceof BankError && e.status === 404) {
    41	      db.prepare("UPDATE intents SET status='failed',error=? WHERE id=?").run(
    42	        'The bank has no record of this operation.',
    43	        intentId,
    44	      );
    45	      recordEvent(ctx, 'transfer.resolved', { status: 'failed', intentId });
    46	      return {
    47	        status: 'failed',
    48	        error: 'The bank has no record of this operation.',
    49	        intentId,
    50	        resolved: true,
    51	      };
    52	    }
    53	    return {
    54	      status: 'unknown',
    55	      reference: intent.bank_reference,
    56	      intentId,
    57	      error: UNKNOWN_MESSAGE,
    58	    };
    59	  }
    60	}
